 for(const t of types){const b=$('piece-tray').querySelector(`[data-arg="${t}"]`);b.setAttribute('aria-pressed',String(s.sel===t&&s.tray[t]>0));b.setAttribute('aria-label',`${t}, ${s.tray[t]} turntables available`);b.disabled=s.tray[t]<=0||(!s.editable&&!n)||n?.phase==='ended'||!!n?.walkies;b.querySelector('.count').textContent=s.tray[t]}

